-- Generated by `python -m pipeline.db` from pipeline/db.py. Do not edit by hand.

CREATE TABLE IF NOT EXISTS bi_forecast (
	year INTEGER NOT NULL, 
	iso3 TEXT NOT NULL, 
	name TEXT NOT NULL, 
	score FLOAT, 
	low FLOAT, 
	high FLOAT, 
	p_top3 FLOAT, 
	rank INTEGER, 
	model TEXT, 
	computed_at TEXT NOT NULL, 
	PRIMARY KEY (year, iso3)
);

CREATE TABLE IF NOT EXISTS bi_rankings (
	category TEXT NOT NULL, 
	iso3 TEXT NOT NULL, 
	name TEXT NOT NULL, 
	rank INTEGER NOT NULL, 
	score FLOAT NOT NULL, 
	market_growth FLOAT, 
	market_size FLOAT, 
	korean_momentum FLOAT, 
	entry_ease FLOAT, 
	p_top3 FLOAT, 
	p_top3_any_weights FLOAT, 
	confidence TEXT, 
	headline TEXT, 
	latest_year INTEGER, 
	computed_at TEXT NOT NULL, 
	PRIMARY KEY (category, iso3)
);

CREATE TABLE IF NOT EXISTS bi_score_history (
	year INTEGER NOT NULL, 
	iso3 TEXT NOT NULL, 
	name TEXT NOT NULL, 
	score FLOAT, 
	rank INTEGER, 
	computed_at TEXT NOT NULL, 
	PRIMARY KEY (year, iso3)
);

CREATE TABLE IF NOT EXISTS commodity_prices (
	source TEXT NOT NULL, 
	commodity TEXT NOT NULL, 
	month TEXT NOT NULL, 
	price FLOAT, 
	unit TEXT, 
	retrieved_at TEXT NOT NULL, 
	run_id TEXT NOT NULL, 
	PRIMARY KEY (source, commodity, month)
);

CREATE TABLE IF NOT EXISTS country_indicators (
	source TEXT NOT NULL, 
	iso3 TEXT NOT NULL, 
	indicator TEXT NOT NULL, 
	year INTEGER NOT NULL, 
	value FLOAT, 
	unit TEXT, 
	source_code TEXT, 
	imputed BOOLEAN, 
	retrieved_at TEXT NOT NULL, 
	run_id TEXT NOT NULL, 
	PRIMARY KEY (source, iso3, indicator, year)
);

CREATE TABLE IF NOT EXISTS data_revisions (
	id SERIAL NOT NULL, 
	run_id TEXT NOT NULL, 
	table_name TEXT NOT NULL, 
	row_key JSON NOT NULL, 
	field TEXT NOT NULL, 
	old_value TEXT, 
	new_value TEXT, 
	detected_at TEXT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS fx_rates (
	source TEXT NOT NULL, 
	date TEXT NOT NULL, 
	base TEXT NOT NULL, 
	quote TEXT NOT NULL, 
	rate FLOAT, 
	retrieved_at TEXT NOT NULL, 
	run_id TEXT NOT NULL, 
	PRIMARY KEY (source, date, base, quote)
);

CREATE TABLE IF NOT EXISTS ingest_events (
	id SERIAL NOT NULL, 
	run_id TEXT NOT NULL, 
	ts TEXT NOT NULL, 
	step TEXT NOT NULL, 
	status TEXT NOT NULL, 
	message TEXT, 
	metrics JSON, 
	PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS ingest_runs (
	run_id TEXT NOT NULL, 
	source TEXT NOT NULL, 
	trigger TEXT NOT NULL, 
	status TEXT NOT NULL, 
	started_at TEXT NOT NULL, 
	finished_at TEXT, 
	rows_fetched INTEGER, 
	rows_inserted INTEGER, 
	rows_updated INTEGER, 
	rows_unchanged INTEGER, 
	rows_invalid INTEGER, 
	error TEXT, 
	ci_run_url TEXT, 
	PRIMARY KEY (run_id)
);

CREATE TABLE IF NOT EXISTS ranking_snapshots (
	id SERIAL NOT NULL, 
	run_id TEXT NOT NULL, 
	computed_at TEXT NOT NULL, 
	category TEXT NOT NULL, 
	variant TEXT NOT NULL, 
	preset TEXT NOT NULL, 
	payload JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS reports (
	week TEXT NOT NULL, 
	generated_at TEXT NOT NULL, 
	title TEXT NOT NULL, 
	headline TEXT NOT NULL, 
	payload JSON NOT NULL, 
	markdown TEXT NOT NULL, 
	PRIMARY KEY (week)
);

CREATE TABLE IF NOT EXISTS tariffs (
	source TEXT NOT NULL, 
	importer_iso3 TEXT NOT NULL, 
	hs TEXT NOT NULL, 
	rate_type TEXT NOT NULL, 
	agreement TEXT NOT NULL, 
	effective_from TEXT NOT NULL, 
	effective_to TEXT, 
	rate_pct FLOAT, 
	source_url TEXT, 
	retrieved_at TEXT NOT NULL, 
	run_id TEXT NOT NULL, 
	PRIMARY KEY (source, importer_iso3, hs, rate_type, agreement, effective_from)
);

CREATE TABLE IF NOT EXISTS trade_flows (
	source TEXT NOT NULL, 
	reporter_iso3 TEXT NOT NULL, 
	partner_iso3 TEXT NOT NULL, 
	flow TEXT NOT NULL, 
	hs TEXT NOT NULL, 
	freq TEXT NOT NULL, 
	period TEXT NOT NULL, 
	value_usd FLOAT, 
	net_kg FLOAT, 
	imputed BOOLEAN, 
	retrieved_at TEXT NOT NULL, 
	run_id TEXT NOT NULL, 
	PRIMARY KEY (source, reporter_iso3, partner_iso3, flow, hs, freq, period)
);

CREATE TABLE IF NOT EXISTS watchlist (
	iso3 TEXT NOT NULL, 
	added_at TEXT NOT NULL, 
	PRIMARY KEY (iso3)
);

