-- Live run feed on the Automation page (Supabase Realtime).
do $$ begin
  alter publication supabase_realtime add table ingest_runs, ingest_events;
exception when duplicate_object then null; end $$;

-- Private bucket for raw upstream responses (raw/{source}/{run_id}.zip).
insert into storage.buckets (id, name, public) values ('raw', 'raw', false) on conflict do nothing;

-- BI: views over the raw data, and a read-only role for BI tools (docs/bi_guide.md).
create or replace view bi_monthly_exports as select partner_iso3 as iso3, substr(hs, 1, 4) as category, period, substr(period, 1, 4) || '-' || substr(period, 5, 2) || '-01' as month, sum(value_usd) as value_usd, sum(net_kg) as net_kg from trade_flows where source = 'kcs_monthly' and flow = 'X' group by partner_iso3, substr(hs, 1, 4), period;
create or replace view bi_annual_trade as select source, reporter_iso3, partner_iso3, flow, hs, cast(period as integer) as year, value_usd, net_kg from trade_flows where freq = 'A';
create or replace view bi_pipeline_runs as select source, status, trigger, started_at, finished_at, rows_fetched, rows_inserted, rows_updated, rows_unchanged, rows_invalid, error from ingest_runs;
do $$ begin
  create role bi_reader nologin;  -- enable with: alter role bi_reader with login password '...';
exception when duplicate_object then null; end $$;
grant usage on schema public to bi_reader;
grant select on bi_rankings to bi_reader;
grant select on bi_forecast to bi_reader;
grant select on bi_score_history to bi_reader;
grant select on bi_monthly_exports to bi_reader;
grant select on bi_annual_trade to bi_reader;
grant select on bi_pipeline_runs to bi_reader;
drop policy if exists "bi read" on bi_rankings;
create policy "bi read" on bi_rankings for select to bi_reader using (true);
drop policy if exists "bi read" on bi_forecast;
create policy "bi read" on bi_forecast for select to bi_reader using (true);
drop policy if exists "bi read" on bi_score_history;
create policy "bi read" on bi_score_history for select to bi_reader using (true);
